/**
 * Return type for useMenuPanelTranslations hook.
 * Provides all localized strings for MenuPanel components.
 */
export interface IUseMenuPanelTranslationsReturn {
    /** Active locale code (e.g., 'en-US', 'es-MX', 'fr-CA') */
    locale: string;
    /** Visible text strings */
    labels: {
        searchPlaceholder: string;
        noResultsFound: string;
        loading: string;
        loadingMore: string;
        filterMenuOptionsByCategory: string;
        menuOptions: string;
        selected: string;
        selectAll: string;
        clearAll: string;
        apply: string;
        cancel: string;
    };
    /**
     * Returns the localised "Search {target}" string with the given target
     * interpolated. Use instead of calling t() inline with the searchAriaLabel key.
     *
     * @example
     * ```ts
     * const { searchAriaLabel, labels } = useMenuPanelTranslations();
     * const label = searchAriaLabel(ariaLabel || labels.menuOptions);
     * ```
     */
    searchAriaLabel: (target: string) => string;
    /**
     * Raw i18next translation function for one-off translations.
     * Use this for dynamic translations not covered by the structured properties above.
     *
     * @example
     * ```ts
     * const { t } = useMenuPanelTranslations();
     * const customLabel = t('MenuPanel:custom.label', 'Default text');
     * ```
     */
    t: (...args: any[]) => any;
}
/**
 * Hook to provide localized strings for MenuPanel components.
 * Returns translations from the MenuPanel namespace, falling back to English defaults.
 *
 * Returned shape:
 * - `labels`:  visible text strings for search, loading states, etc
 * - `locale`:  active i18n language tag (resolvedLanguage takes priority)
 * - `t`:       raw i18next `t` function for one-off translations
 */
export declare function useMenuPanelTranslations(): IUseMenuPanelTranslationsReturn;
